// Naive: O(2^n) - recomputes the same subproblems
int fibSlow(int n) { return n < 2 ? n : fibSlow(n-1) + fibSlow(n-2); }

// Memoization (top-down): O(n) - each fib(i) computed once
int fibMemo(int n, Integer[] memo) {
    if (n < 2) return n;
    if (memo[n] != null) return memo[n];
    return memo[n] = fibMemo(n-1, memo) + fibMemo(n-2, memo);
}

// Tabulation (bottom-up): O(n) time, O(1) space
int fibTab(int n) {
    if (n < 2) return n;
    int a = 0, b = 1;
    for (int i = 2; i <= n; i++) { int c = a + b; a = b; b = c; }
    return b;
}
