int fib(int n) {
    if (n < 2) return n;
    int a = 0, b = 1;
    for (int i = 2; i <= n; i++) {            // fill from base up
        int c = a + b; a = b; b = c;          // rolling -> O(1) space
    }
    return b;
}
// No recursion (no stack overflow), space optimized to O(1).
